mapper.select:
select mn.* from Archive_Directory_Group mn where (mn.Adg_Type='02' and mn.Adg_Group_Id=#{userInfo.id})
or ( mn.Adg_Type='01' and mn.Adg_Group_Id in
#{depId}
)

select

sr.Role_Name as roleName,
sr.Role_Code as roleCode,
mn.*
from Archive_Directory_Group mn
left join SYS_Role sr on sr.Role_ID=mn.Adg_Role

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Ad_Id=#{params.adId}
    
    
        and mn.Adg_Type=#{params.adgType}
    
    
        and INSRT(mn.Adg_Name,#{params.adgName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
